struct Window {
    std::vector<float> w;
    double coherentGain;  // sum(w)/N
    double enbwBins;      // N*sum(w^2)/sum(w)^2
};
Window makeHann(size_t N);

questions.modelAnswer:
Window makeHann(size_t N) {
    Window r;
    r.w.resize(N);
    double s = 0.0, s2 = 0.0;
    for (size_t n = 0; n < N; ++n) {
        // periodic: divide by N, not N-1; compute in double
        double v = 0.5 - 0.5 * std::cos(2.0 * M_PI * double(n) / double(N));
        r.w[n] = static_cast<float>(v);
        s += v;
        s2 += v * v;
    }
    r.coherentGain = (N > 0) ? s / N : 0.0;          // 0.5
    r.enbwBins = (s > 0) ? N * s2 / (s * s) : 0.0;    // 1.5
    return r;
}

