#include <cstdint>
#include <cstdio>
int16_t mulQ15(int16_t x, int16_t w) {
    int32_t p = int32_t(x) * w;
    return int16_t((p + (1 << 14)) >> 15);
}
int main() {
    std::printf("%d %d\n", mulQ15(-32768, -32768),
                mulQ15(-32768, 32767));
}
